def move_ee(arm, target, grip=None, max_steps=50, position_step=0.012,
            rotation_step=0.08, position_tolerance=0.003, rotation_tolerance=0.02, other_grip=None):
    obs = get_observation()
    state = obs['state']
    key = arm + '_ee_pose'
    start = np.array(state[key], dtype=float)
